recognized_test_commands.command:
/bin/bash -lc "cat > utils/slice/iterator_test.go <<'EOF'
package slice_test

import (
	\"slices\"
	\"testing\"

	\"github.com/navidrome/navidrome/utils/slice\"
)

// A chunk collector must preserve earlier yielded chunks after collecting later ones.
func TestCollectChunksKeepsYieldedChunksIndependent(t *testing.T) {
	var chunks [][]int
	for chunk := range slice.CollectChunks(2, slices.Values([]int{1, 2, 3, 4, 5})) {
		chunks = append(chunks, chunk)
	}
	if "'!slices.Equal(chunks[0], []int{1, 2}) || !slices.Equal(chunks[1], []int{3, 4}) || !slices.Equal(chunks[2], []int{5}) {
		t.Fatalf("chunks changed after later yields: %v", chunks)
	}
	chunks[0][0] = 99
	if chunks[1][0] != 3 {
		t.Fatalf("modifying first chunk changed second: %v", chunks)
	}
}
EOF
GOTOOLCHAIN=local GOPROXY=off go test ./utils/slice -run TestCollectChunksKeepsYieldedChunksIndependent -count=1'
